#include "menu_tools.h"
#include "menu_model.h"
#include "game_session.h"
#include <QtWidgets>
namespace cf {
bool menuBuilders(QWidget *parent,Project &project){
 Project draft=project;QDialog dialog(parent);dialog.setWindowTitle("Menu tools — text, keyboards & saves");dialog.resize(1020,760);auto *root=new QVBoxLayout(&dialog);auto *tabs=new QTabWidget;root->addWidget(tabs,1);
 auto table=[](QStringList headers){auto *t=new QTableWidget(0,headers.size());t->setHorizontalHeaderLabels(headers);t->horizontalHeader()->setSectionResizeMode(QHeaderView::ResizeToContents);t->horizontalHeader()->setStretchLastSection(true);return t;};
 auto item=[](QTableWidget *t,int row,int col,QString value){t->setItem(row,col,new QTableWidgetItem(value));};
 auto spin=[](QTableWidget *t,int row,int col,int value,int low,int high){auto *s=new QSpinBox;s->setRange(low,high);s->setValue(value);t->setCellWidget(row,col,s);return s;};
 auto cell=[](QTableWidget*t,int row,int col){return t->item(row,col)?t->item(row,col)->text():QString();};
 auto number=[](QTableWidget*t,int row,int col){auto *s=qobject_cast<QSpinBox*>(t->cellWidget(row,col));return s?s->value():0;};
 auto *textPage=new QWidget;auto *textLayout=new QVBoxLayout(textPage);textLayout->addWidget(new QLabel("Text fields store player input. Use {field_id} in dialogue and menus. Each field holds 1–20 ASCII characters."));auto *texts=table({"Field ID","Initial text","Maximum characters"});texts->setObjectName("textFieldsTable");textLayout->addWidget(texts,1);
 auto addText=[&](TextField field){int row=texts->rowCount();texts->insertRow(row);item(texts,row,0,field.id);item(texts,row,1,field.initial);spin(texts,row,2,field.limit,1,20);};for(auto &t:draft.textFields)addText(t);
 auto *textButtons=new QHBoxLayout;auto *newText=new QPushButton("+ Text field"),*deleteText=new QPushButton("Remove selected field");textButtons->addWidget(newText);textButtons->addWidget(deleteText);textButtons->addStretch();textLayout->addLayout(textButtons);QObject::connect(newText,&QPushButton::clicked,&dialog,[&]{if(texts->rowCount()<8)addText({"text_"+QString::number(texts->rowCount()+1),"",12});});QObject::connect(deleteText,&QPushButton::clicked,&dialog,[&]{if(texts->currentRow()>=0)texts->removeRow(texts->currentRow());});tabs->addTab(textPage,"Text fields");
 auto *keyboardPage=new QWidget;auto *keyboardLayout=new QVBoxLayout(keyboardPage);keyboardLayout->addWidget(new QLabel("Keys are laid out left to right, then top to bottom. Delete, OK and Cancel keys are appended automatically. Space is a usable key."));auto *keys=table({"Keyboard ID","Title","Characters / order","Columns","Grid X","Grid Y"});keys->setObjectName("keyboardTable");keyboardLayout->addWidget(keys,1);
 std::function<void()> refreshKeyboard;
 auto addKeyboard=[&](Keyboard k){int row=keys->rowCount();keys->insertRow(row);item(keys,row,0,k.id);item(keys,row,1,k.name);item(keys,row,2,k.characters);for(auto *s:{spin(keys,row,3,k.columns,1,10),spin(keys,row,4,k.x,0,18),spin(keys,row,5,k.y,5,14)})QObject::connect(s,&QSpinBox::valueChanged,&dialog,[&]{if(refreshKeyboard)refreshKeyboard();});keys->setCurrentCell(row,0);};for(auto &k:draft.keyboards)addKeyboard(k);
 auto *keyButtons=new QHBoxLayout;for(auto preset:{QString("Name keyboard"),QString("Digits keyboard")}){auto *b=new QPushButton("+ "+preset);keyButtons->addWidget(b);QObject::connect(b,&QPushButton::clicked,&dialog,[&,preset]{if(keys->rowCount()>=8)return;Keyboard k;k.id="keyboard_"+QString::number(keys->rowCount()+1);if(preset.startsWith("Digits")){k.name="Enter number";k.characters="0123456789";k.columns=5;}addKeyboard(k);});}auto *deleteKey=new QPushButton("Remove keyboard");keyButtons->addWidget(deleteKey);keyboardLayout->addLayout(keyButtons);QObject::connect(deleteKey,&QPushButton::clicked,&dialog,[&]{if(keys->currentRow()>=0)keys->removeRow(keys->currentRow());});auto *preview=new QLabel;preview->setAlignment(Qt::AlignCenter);preview->setMinimumHeight(288);keyboardLayout->addWidget(preview);tabs->addTab(keyboardPage,"Keyboard builder");
 auto readTables=[&]{draft.textFields.clear();for(int row=0;row<texts->rowCount();++row)draft.textFields<<TextField{cell(texts,row,0).trimmed(),cell(texts,row,1),number(texts,row,2)};draft.keyboards.clear();for(int row=0;row<keys->rowCount();++row)draft.keyboards<<Keyboard{cell(keys,row,0).trimmed(),cell(keys,row,1),cell(keys,row,2),number(keys,row,3),number(keys,row,4),number(keys,row,5)};};
 auto showKeyboard=[&]{readTables();int index=keys->currentRow();if(index<0||index>=draft.keyboards.size()){preview->clear();return;}if(!draft.validateMenus().isEmpty()){preview->setText("Adjust the grid or keys to fit the 20×18 screen. Apply shows any validation errors.");return;}auto temp=draft;if(temp.textFields.isEmpty())temp.textFields<<TextField{"preview","",12};GameSession session;session.configure(temp);session.state.keyboard_id=index;session.state.keyboard_active=1;session.state.keyboard_limit=temp.textFields[0].limit;preview->setPixmap(QPixmap::fromImage(textScreenImage(session.keyboardLines(),{0,0,20,18},temp.target=="gb").scaled(320,288)));};refreshKeyboard=showKeyboard;QObject::connect(keys,&QTableWidget::cellChanged,&dialog,[&]{showKeyboard();});QObject::connect(keys,&QTableWidget::currentCellChanged,&dialog,[&](int,int,int,int){showKeyboard();});for(auto *s:keys->findChildren<QSpinBox*>())QObject::connect(s,&QSpinBox::valueChanged,&dialog,[&]{showKeyboard();});
 auto *savePage=new QWidget;auto *saveLayout=new QVBoxLayout(savePage);auto *enabled=new QCheckBox("Enable battery-backed cartridge saves");enabled->setChecked(draft.saveConfig.enabled);saveLayout->addWidget(enabled);auto *saveForm=new QFormLayout;auto *slotCount=new QSpinBox;slotCount->setRange(1,3);slotCount->setValue(draft.saveConfig.slotCount);saveForm->addRow("Save slots",slotCount);auto *identity=new QLabel(draft.saveConfig.id.isEmpty()?"Created when enabled":draft.saveConfig.id);identity->setTextInteractionFlags(Qt::TextSelectableByMouse);saveForm->addRow("Save identity",identity);auto *pause=new QComboBox;pause->addItem("No pause menu",QString());for(auto &s:draft.scenes)if(s.kind=="screen")pause->addItem(s.name,s.id);pause->setCurrentIndex(qMax(0,pause->findData(draft.pauseMenu)));saveForm->addRow("Start button opens",pause);saveLayout->addLayout(saveForm);
 auto *detected=new QListWidget;detected->setObjectName("detectedSaveFields");saveLayout->addWidget(new QLabel("Detected project data — uncheck fields to omit them. Newly added fields are included automatically."));saveLayout->addWidget(detected,1);
 auto checkItem=[&](QString label,QString key,bool checked){auto *i=new QListWidgetItem(label,detected);i->setData(Qt::UserRole,key);i->setFlags(i->flags()|Qt::ItemIsUserCheckable);i->setCheckState(checked?Qt::Checked:Qt::Unchecked);};
 auto detect=[&]{QSignalBlocker blocker(detected);readTables();detected->clear();for(auto &v:draft.variables)checkItem("Variable / "+v.id,"v:"+v.id,draft.saveConfig.variables&&!draft.saveConfig.excludedVariables.contains(v.id));for(auto &t:draft.textFields)checkItem("Text / "+t.id+QString(" (%1 characters)").arg(t.limit),"t:"+t.id,draft.saveConfig.text&&!draft.saveConfig.excludedText.contains(t.id));for(auto &s:draft.storages)checkItem("Storage / "+s.name+QString(" (%1 item types)").arg(draft.items.size()),"s:"+s.id,draft.saveConfig.storages&&!draft.saveConfig.excludedStorages.contains(s.id));};
 auto *options=new QHBoxLayout;auto *location=new QCheckBox("Scene, area & player position"),*timers=new QCheckBox("Timers"),*random=new QCheckBox("RNG state");location->setChecked(draft.saveConfig.position);timers->setChecked(draft.saveConfig.timers);random->setChecked(draft.saveConfig.random);options->addWidget(location);options->addWidget(timers);options->addWidget(random);saveLayout->addLayout(options);
 auto *usage=new QLabel;usage->setWordWrap(true);saveLayout->addWidget(usage);auto *generate=new QCheckBox("Generate missing save write/read/check/erase scripts for every slot");generate->setChecked(true);saveLayout->addWidget(generate);auto *help=new QLabel("Saves use two checksum-protected copies per slot in 8 KiB cartridge RAM. Changing the saved schema rejects older saves. ROM emulators store this RAM in a .sav file; save names are in-game labels, not host filenames.\nPreview saves use a separate file in application data. Transient character movement/health, audio and open menus are not saved; persist story progress in variables.");help->setWordWrap(true);saveLayout->addWidget(help);tabs->addTab(savePage,"Save builder");
 auto readSave=[&]{auto &c=draft.saveConfig;c.enabled=enabled->isChecked();c.slotCount=slotCount->value();c.position=location->isChecked();c.timers=timers->isChecked();c.random=random->isChecked();c.variables=c.text=c.storages=true;c.excludedVariables.clear();c.excludedText.clear();c.excludedStorages.clear();for(int i=0;i<detected->count();++i){auto *item=detected->item(i);if(item->checkState()==Qt::Checked)continue;auto key=item->data(Qt::UserRole).toString();if(key.startsWith("v:"))c.excludedVariables<<key.mid(2);if(key.startsWith("t:"))c.excludedText<<key.mid(2);if(key.startsWith("s:"))c.excludedStorages<<key.mid(2);}draft.pauseMenu=pause->currentData().toString();};
 auto summary=[&]{readSave();GameSession s;s.configure(draft);usage->setText(QString("%1 bytes per record · %2 bytes reserved for %3 slots with recovery copies.\nPreview save: %4").arg(cf_save_size(&s.definition)).arg(slotCount->value()*CF_SAVE_RECORD*2).arg(slotCount->value()).arg(s.previewSavePath()));};detect();summary();QObject::connect(detected,&QListWidget::itemChanged,&dialog,[&]{summary();});for(auto *c:{enabled,location,timers,random})QObject::connect(c,&QCheckBox::toggled,&dialog,[&]{summary();});QObject::connect(slotCount,&QSpinBox::valueChanged,&dialog,[&]{summary();});QObject::connect(tabs,&QTabWidget::currentChanged,&dialog,[&](int page){if(page==1)showKeyboard();if(page==2){detect();summary();}});
 auto *status=new QLabel;status->setWordWrap(true);root->addWidget(status);auto *buttons=new QDialogButtonBox(QDialogButtonBox::Ok|QDialogButtonBox::Cancel);root->addWidget(buttons);QObject::connect(buttons,&QDialogButtonBox::rejected,&dialog,&QDialog::reject);QObject::connect(buttons,&QDialogButtonBox::accepted,&dialog,[&]{readTables();readSave();if(draft.saveConfig.enabled){if(draft.saveConfig.id.isEmpty())draft.saveConfig.id=QUuid::createUuid().toString(QUuid::WithoutBraces);if(generate->isChecked())generateSaveScripts(draft);}auto errors=draft.validate();if(!errors.isEmpty()){status->setText(errors.mid(0,8).join('\n'));return;}project=draft;dialog.accept();});showKeyboard();return dialog.exec()==QDialog::Accepted;
}
}
